from reportlib import *
import numpy as np

def run():
 w=1;p=part('UNRESOLVED','Week1 artifact gap','What experiments were actually executed under Week1?',status='UNKNOWN',finding='No Week1-specific notebook, result directory or machine-readable outcome artifact was located. Baseline artifacts used by Week2 cannot be retroactively assigned to Week1.',caveat='EVIDENCE GAP — manual review required. No chronological result is inferred from old Markdown or chat history.')
 write_week(1,'Recover Week1 activities without filling gaps from later results or narrative.',[p],checks=['Week1-specific notebooks/results/configs/source paths were absent in initial discovery.'],negative='No completed result artifact was found.',limits='EVIDENCE GAP — manual review required.',transition='Week2 has a concrete fixed-k response matrix; that does not establish a Week1 experiment.');print('Legacy Week1',audit_legacy(1))
 raw='results/week2/raw/dev_fixed_k_matrix.jsonl';d=pd.read_json(ROOT/raw,lines=True);s=frame('results/week2/processed/dev_fixed_k_summary.csv');a=d.groupby(['k','method']).agg(queries=('question_id','nunique'),F1=('token_f1','mean'),EM=('exact_match','mean'),tokens=('context_tokens','mean')).reset_index()
 assert len(d)==1617 and not d.duplicated(['question_id','k']).any() and d.question_id.nunique()==231 and d.paper_id.nunique()==86
 assert np.allclose(a.F1,s.sort_values('k').mean_f1,atol=.000051)
 matrix=d.pivot(index='question_id',columns='k',values='token_f1');orc=pd.DataFrame([dict(actions='SARA {0,2,4,5,6,8}',retrospective_oracle_F1=matrix[[0,2,4,5,6,8]].max(axis=1).mean()),dict(actions='Full sweep including RAG k10',retrospective_oracle_F1=matrix.max(axis=1).mean())]);dist=frame('results/week2/processed/best_k_distribution.csv')
 cfg='configs/week2/sweep_config.yaml';ctx=[cfg,'notebooks/week2/week2_dev_fixed_k_sweep.ipynb'];base=dict(dataset='QASPER local DEV: 231 queries / 86 papers',retrieval='BM25 top10; SFR passage embeddings for SARA latent interface',reader='Mistral-7B-Instruct-v0.2; separately fine-tuned SARA/RAG checkpoints',seed=42,decoding='greedy; max_new_tokens=64; bfloat16')
 parts=[part('FIXED-K','Fixed-k response surface','How do answer quality and context cost change as verbatim-passage budget k increases?',paths=[raw,'results/week2/processed/dev_fixed_k_summary.csv'],tables=[(raw,a,'Raw-result recomputed fixed-k metrics')],design=base|{'actions':[0,2,4,5,6,8,10]},finding='SARA k8 has mean F1 0.3950 versus parent k5 0.3629; separate plain-RAG k10 has F1 0.4090. Increasing text budget improves these aggregate point estimates.',caveat='k10 uses the separately trained RAG checkpoint: this is a whole-system comparison, not isolated causal evidence that latent compression hurts. Synthesized total latency includes estimated components and is not measured end-to-end.',decision='best_static_baseline.json freezes SARA k8 within the SARA action set.'),part('ORACLE','Retrospective action headroom','Would per-query best-tested k have headroom over the best static SARA budget?',paths=['results/week2/processed/per_query_best_k.csv','results/week2/processed/oracle_vs_static_summary.json'],tables=[(raw,orc,'Retrospective ceilings; not deployable policies'),('results/week2/processed/best_k_distribution.csv',dist,'Smallest-k tie-broken distribution')],design=base,finding='The retrospective SARA oracle is about 0.5008 F1 versus static k8 0.3950; the full sweep oracle is about 0.5264. These are outcome-selected ceilings.',caveat='Smallest-k ties inflate apparent budget disagreement. Oracle choices use gold-scored outcomes and cannot be fair deployment baselines.'),part('FREEZE','Development integrity and retained baseline','Is the query/action grid complete and which reference was frozen for later modeling?',paths=['results/week2/processed/best_static_baseline.json','results/week2/processed/week2_validation_checkpoint.json'],tables=[('results/week2/processed/best_static_baseline.json',pd.DataFrame(flat(obj('results/week2/processed/best_static_baseline.json'))),'Frozen numerical baseline fields')],design=base,finding='The 1,617-row matrix is exactly 231 queries × seven actions with no duplicate query/k pairs; static SARA k8 is retained. The checkpoint records zero train/dev paper overlap at that historical stage.',caveat='A historical TEST-untouched assertion is a time-specific receipt, not a claim that TEST remains untouched in later weeks.')]
 write_week(2,'Measure the static SARA text/latent representation-budget frontier and retrospective adaptive headroom.',parts,ctx,checks=['Recomputed F1/EM/token means from all 1,617 raw JSONL rows; F1 agrees with summary to 4-decimal rounding.','Verified 231 unique queries, 86 papers, seven actions and zero duplicate pairs.'],transition='Week3 code/config restricts deployable-oracle actions to {2,4,5,6,8}, adds epsilon targets and tie-aware analysis.',decision='SARA k8 retained; RAG k10 tracked separately.',negative='No learned allocator or prospective generalization is evaluated.',limits='Small local DEV cohort, outcome-selected ceilings, shared-query dependence and different SARA/RAG checkpoints.');print('Legacy Week2',audit_legacy(2))
 qpath='results/week3/processed/dev_quality_oracle.csv';q=frame(qpath);epath='results/week3/processed/epsilon_summary.csv';es=frame(epath);eraw=frame('results/week3/processed/epsilon_oracle_all.csv');assert len(q)==231 and len(eraw)==924
 assert np.allclose(q.best_f1_qual,q[['f1_k2','f1_k4','f1_k5','f1_k6','f1_k8']].max(axis=1))
 recom=eraw.groupby('epsilon').agg(n=('question_id','size'),mean_k=('selected_k_epsilon','mean'),F1=('selected_f1','mean'),regret=('f1_regret','mean'),tokens=('context_tokens_cost','mean')).reset_index();assert np.allclose(recom.F1,es.mean_f1,atol=.000051)
 human='results/week3/human_audit/human_scoring_template.csv';h=frame(human);print('HUMAN schema',h.shape,list(h.columns));hs=frame('results/week3/human_audit/human_audit_summary.csv');print('human summary',hs.to_string(index=False)[:800])
 hh=obj('results/week3/processed/heterogeneity_summary.json');sig=frame('results/week3/processed/feature_signal_analysis.csv')
 b3=dict(dataset='Same 231-query / 86-paper local QASPER DEV cohort',actions='Primary {2,4,5,6,8}; k0/k10 diagnostic only',seed=42)
 parts=[part('QUALITY-ORACLE','Deployable-action-space oracle and tie audit','How much adaptive headroom remains after excluding pure compression and the separate RAG checkpoint?',paths=[qpath,'results/week3/processed/heterogeneity_summary.json'],tables=[('results/week3/processed/quality_oracle_distribution.csv',frame('results/week3/processed/quality_oracle_distribution.csv'),'Smallest-budget quality oracle distribution'),('results/week3/processed/heterogeneity_summary.json',pd.DataFrame(flat({'tie_aware':hh['tie_aware_k8_status'],'bootstrap':hh['paper_clustered_bootstrap_cis']})),'Tie-aware counts and stored uncertainty')],design=b3,finding=f'The restricted retrospective oracle mean is {q.best_f1_qual.mean():.6f}, with mean gain {q.oracle_gain.mean():.6f} over k8. Only 29.44% of queries strictly improve over k8; 60.61% tie k8 with a smaller action.',stats='Stored bootstrap uses 1,000 paper-cluster resamples (86 papers), seed42, nominal95% intervals. Stored headroom CI is [0.0693,0.1226]. Bootstrap-mean point fields are not substituted for raw-sample means.',caveat='Retrospective oracle only. Its difference from Week2 oracle is mechanically explained by removing k0 from the primary action set, not a failed reproduction.'),part('EPSILON','Epsilon-tolerant cost-aware target','Can smaller retrospective actions preserve quality within a declared tolerance?',paths=[epath,'results/week3/processed/epsilon_oracle_all.csv','results/week3/processed/selected_epsilon.json'],tables=[(epath,es,'All epsilon candidates'),('results/week3/processed/epsilon_oracle_all.csv',recom,'Offline recomputed means')],design=b3|{'epsilon_candidates':[0,.01,.02,.05]},finding='The development-selected epsilon is 0.01: stored mean F1 0.4894, mean k3.49 and mean context 841.3 tokens, about 52.16% below k8. Primary action-set feasibility is 100%.',caveat='Cost-aware choices are retrospective oracle labels, not achievable inference results; epsilon was chosen on this same development cohort.',decision='selected_epsilon.json retains epsilon0.01 for later modeling.'),part('FEATURES','Pregeneration feature signal','Do simple retrieval/query observables correlate with oracle action labels?',paths=['results/week3/processed/feature_signal_analysis.csv'],tables=[('results/week3/processed/feature_signal_analysis.csv',sig.drop(columns=['interpretation'],errors='ignore'),'Exploratory feature/target associations')],design=b3,finding='Recorded feature associations are weak; for example n_high versus budget has Spearman rho −0.1421 (nominal p0.0308). This motivates testing predictors but does not establish out-of-sample predictive utility.',stats='Recorded Spearman/Pearson/Kruskal–Wallis p-values are exploratory; no multiplicity-corrected confirmatory family is established.',caveat='Many feature/target comparisons and reused development labels; significance alone does not imply meaningful predictive quality.'),part('HUMAN-AUDIT','Blinded human-scoring package','Do human ratings independently confirm automatic-score differences?',paths=[human,'results/week3/human_audit/human_audit_summary.csv','results/week3/processed/week3_gate.json'],tables=[('results/week3/human_audit/human_audit_summary.csv',hs,'Saved audit status/coverage')],design=b3|{'planned_questions':50,'planned_actions':[2,5,10]},status='IMPLEMENTED',finding='The gate explicitly records PENDING_MANUAL_EVALUATION. A scoring template/package exists; completed human judgment evidence is not established.',caveat='Do not treat prepared blinded items or machine predictions as completed human evaluation.')]
 write_week(3,'Quantify tie-aware adaptive headroom, freeze epsilon targets, inspect observable signals and prepare blinded human validation.',parts,['configs/week3/week3_config.yaml','notebooks/week3/week3_oracle_target_analysis.ipynb','notebooks/week3/week3_oracle_epsilon_human_audit.ipynb'],checks=['231 oracle rows and 924 epsilon rows verified; raw maxima and epsilon F1 means match stored analyses within rounding.','Week2/Week3 oracle values refer to different action sets; no silent source conflation.'],transition='Week4 notebook names/configs instantiate feature validation and learned QCCA model benchmarking.',decision='epsilon0.01 retained; proceed gate concerns modeling readiness, not successful human validation.',negative='Human evaluation remains pending; no deployable adaptive controller is established.',limits='Development exposure, weak associations, oracle label ties and small paper count.');print('Legacy Week3',audit_legacy(3))
if __name__=='__main__':run()
